<script>
(() => {
 const input = document.getElementById('course-search');
 const cards = Array.from(document.querySelectorAll('[data-course-title]'));
 const status = document.getElementById('search-status');
 const noResults = document.getElementById('no-results');
 const normalize = text => text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('pt-BR').trim();
 input.addEventListener('input', () => {
   const query = normalize(input.value); let count = 0;
   cards.forEach(card => { const match = normalize(card.dataset.courseTitle).includes(query); card.hidden = !match; if (match) count++; });
   status.textContent = count + (count === 1 ? ' curso disponível' : ' cursos disponíveis');
   noResults.hidden = count !== 0 || cards.length === 0;
 });
})();
</script></body></html>
